  5	/**
  6	 * A class representing shared characteristics of animals.
  7	 *
  8	 * @version 01.03.22
  9	 */
 10	public abstract class Animal extends LivingEntity
 11	{
 12	    // Distinguishes between male and female to determine breeding
 13	    private boolean isMale;
 14	    // whether or not the weather is fog
 15	    private boolean fog;
 16	    // The animal's food level
 17	    private int foodLevel;
 18	    //whether the animal has a disease or not
 19	    private boolean disease;
 20	    // The animal's age.
 21	    private int age;
 22	
 23	    // A shared random number generator to control breeding.
 24	    private static final Random rand = Randomizer.getRandom();
 25	    
 26	    /**
 27	     * Create a new animal at location in field.
 28	     * 
 29	     * @param field The field currently occupied.
 30	     * @param location The location within the field.
 31	     */
 32	    public Animal(Field field, Location location) {
 33	        super(field, location);
 34	        fog = false;
 35	        disease = false;
 36	    }
 37	    
 38	    /**
 39	     * Make this animal act - that is: make it do
 40	     * whatever it wants/needs to do.
 41	     * @param newAnimals A list to receive newly born animals.
 42	     */
 43	    abstract public void act(List<Animal> newAnimals, int time);
 44	
 45	    /**
 46	     * Return the animal's gender.
 47	     * @return True if the animal is male, false if it is female.
 48	     */
 49	    protected boolean getGender(){return isMale;}
 50	
 51	    /**
 52	     * Randomly assigns an animal a gender
 53	     */
 54	    protected void setGender() {
 55	        Random rand = Randomizer.getRandom();
 56	        if (rand.nextInt(2) == 1) {
 57	            isMale = true;
 58	        }
 59	        else {
 60	            isMale = false;
 61	        }
 62	    }
 63	
 64	    /**
 65	     * assigns true to fog field
 66	     */
 67	    protected void setFog() { fog = true; }
 68	
 69	    /**
 70	     * assigns false to fog field
 71	     */
 72	    protected void resetFog(){ fog = false; }
 73	
 74	    /**
 75	     * returns the fog field
 76	     * @return true if the weather is fog, false if it is not
 77	     */
 78	    protected boolean getFog() {return fog;}
 79	
 80	    /**
 81	     * takes a food level parameter and assigns it to the foodLevel field
 82	     * @param foodLevel the value to be assigned to foodLevel
 83	     */
 84	    protected void setFoodLevel(int foodLevel){ this.foodLevel = foodLevel; }
 85	
 86	    /**
 87	     * decrements foodLevel by 1
 88	     */
 89	    protected void decrementHealth(){ foodLevel--; }
 90	
 91	    /**
 92	     * gives an animal a disease
 93	     * 1 in 100 chance of assigning true to disease
 94	     */
 95	    protected void giveDisease() {
 96	        Random rand = Randomizer.getRandom();
 97	        if (rand.nextInt(101) == 1) {
 98	            disease = true;
 99	        }
100	    }
101	
102	    /**
103	     * returns whether the animal has a disease or not
104	     * @return true if the animal has a disease, false if they don't
105	     */
106	    protected boolean getDisease() { return disease; }
107	
108	    /**
109	     * assigns false to disease
110	     */
111	    protected void resetDisease() { disease = false; }
112	
113	    /**
114	     * if an animal has a disease, this method spreads it to animals
115	     * in adjacent locations
116	     */
117	    protected void spreadDisease() {
118	        Field field = getField();
119	        List<Location> adjacent = field.adjacentLocations(getLocation());
120	        Iterator<Location> it = adjacent.iterator();
121	        while(it.hasNext()) {
122	            Location where = it.next();
123	            Object animal = field.getObjectAt(where);
124	            if(animal instanceof Animal) {
125	                Animal diseaseAnimal = (Animal) animal;
126	                diseaseAnimal.giveDisease();
127	                diseaseAnimal.decrementHealth();
128	            }
129	        }
130	    }
131	
132	    /**
133	     * Breed new offspring into free adjacent locations.
134	     * @param newAnimals A list to receive newly born animals.
135	     * @param BREEDING_AGE The minimum age required to breed.
136	     * @param BREEDING_PROBABILITY The likelihood of breeding.
137	     * @param MAX_LITTER_SIZE The maximum number of births.
138	     */
139	    protected void breedOffspring(List<Animal> newAnimals, int BREEDING_AGE,
140	            double BREEDING_PROBABILITY, int MAX_LITTER_SIZE) {
141	        if(giveBirth(BREEDING_AGE)) {
142	            Field field = getField();
143	            List<Location> free = field.getFreeAdjacentLocations(getLocation());
144	            int births = breed(BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);
145	            for (int b = 0; b < births && free.size() > 0; b++) {
146	                Location loc = free.remove(0);
147	                newAnimals.add(createOffspring(field, loc));
148	            }
149	        }
150	    }
151	
152	    /**
153	     * Create a new offspring of this animal's species.
154	     * @param field The field occupied by the offspring.
155	     * @param location The offspring's location.
156	     * @return A new animal instance.
157	     */
158	    protected abstract Animal createOffspring(Field field, Location location);
159	
160	    /**
161	     * Move to a new location if one exists, otherwise die.
162	     * @param newLocation The destination location, or null.
163	     */
164	    protected void moveOrDie(Location newLocation) {
165	        if(newLocation != null) {
166	            setLocation(newLocation);
167	        }
168	        else {
169	            setDead();
170	        }
171	    }
172	
173	    /**
174	     * takes an age parameter and assigns it to the age field
175	     * @param age the value to be assigned to the age field
176	     */
177	    protected void setAge(int age) { this.age = age; }
178	
179	    /**
180	     * Generate a number representing the number of births,
181	     * if it can breed.
182	     * @return The number of births (may be zero).
183	     */
184	    protected int breed(int BREEDING_AGE, double BREEDING_PROBABILITY, int MAX_LITTER_SIZE) {
185	        int births = 0;
186	        if(canBreed(BREEDING_AGE) && rand.nextDouble() <= BREEDING_PROBABILITY) {
187	            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
188	        }
189	        return births;
190	    }
191	
192	    /**
193	     * Check whether or not this animal is to give birth at this step.
194	     * animals are checked to be: of the same species(class), different genders and
195	     *  of breeding age
196	     * @param BREEDING_AGE the minimum age this animal must be to breed
197	     * @retyrn true if the animal can breed, false if it can not
198	     */
199	    protected boolean giveBirth(int BREEDING_AGE) {
200	        Field field = getField();
201	        List<Location> adjacent = field.adjacentLocations(getLocation());
202	        Iterator<Location> it = adjacent.iterator();
203	        while(it.hasNext()) {
204	            Location where = it.next();
205	            Object animal = field.getObjectAt(where);
206	            if (animal != null) {
207	                if (animal.getClass() == this.getClass()) {
208	                    Animal adjAnimal = (Animal) animal;
209	                    if (this.getGender() != adjAnimal.getGender()) {
210	                        if (age >= BREEDING_AGE) {
211	                            return true;
212	                        }
213	                    }
214	                }
215	            }
216	        }
217	        return false;
218	    }
219	
220	
221	    /**
222	     * checks to see if the animal has reached breeding age
223	     * @param BREEDING_AGE the minimum an animal must be in order to breed
224	     * @return true if the animal is of breeding age
225	     */
226	    protected boolean canBreed(int BREEDING_AGE)
227	    {
228	        return age >= BREEDING_AGE;
229	    }
230	
231	    /**
232	     * make the animal more hungry by decreasing its health
233	     * if the foodLevel is less than or equal to 0, set the animal to dead
234	     */
235	    protected void incrementHunger() {
236	        decrementHealth();
237	        if(foodLevel <= 0) {
238	            setDead();
239	        }
240	    }
241	
242	    /**
243	     * Increase the age. This could result in the animal's death.
244	     */
245	    protected void incrementAge(int MAX_AGE) {
246	        age++;
247	        if(age > MAX_AGE) {
248	            setDead();
249	        }
250	    }
251	
252	}

