  5	/**
  6	 * A simple model of an ant.
  7	 * Ants age, move, eat acacia and grass, breed, and die.
  8	 *
  9	 * @version 01.03.22
 10	 */
 11	public class Ant extends Animal
 12	{
 13	    // Characteristics shared by all ants (class variables).
 14	
 15	    // The age at which an ant can start to breed.
 16	    private static final int BREEDING_AGE = 20;
 17	    // The age to which an ant can live.
 18	    private static final int MAX_AGE = 400;
 19	    // The likelihood of an ant breeding.
 20	    private static final double BREEDING_PROBABILITY = 0.32;
 21	    // The maximum number of births.
 22	    private static final int MAX_LITTER_SIZE = 14;
 23	    // The food value of a single acacia. In effect, this is the
 24	    // number of steps an ant can go before it has to eat again.
 25	    private static final int ACACIA_FOOD_VALUE = 60;
 26	    // The food value of a single grass. In effect, this is the
 27	    // number of steps an ant can go before it has to eat again.
 28	    private static final int GRASS_FOOD_VALUE = 60;
 29	    // A shared random number generator to control breeding.
 30	    private static final Random rand = Randomizer.getRandom();
 31	
 32	    /**
 33	     * Create an ant. An ant can be created as a newborn (age zero
 34	     * and not hungry) or with a random age and food level.
 35	     *
 36	     * @param randomAge If true, the ant will have random age and hunger level.
 37	     * @param field The field currently occupied.
 38	     * @param location The location within the field.
 39	     */
 40	    public Ant(boolean randomAge, Field field, Location location) {
 41	        super(field, location);
 42	        this.setGender();
 43	        if(randomAge) {
 44	            setAge(rand.nextInt(MAX_AGE));
 45	            setFoodLevel(rand.nextInt(ACACIA_FOOD_VALUE));
 46	        }
 47	        else {
 48	            setAge(0);
 49	            setFoodLevel(ACACIA_FOOD_VALUE);
 50	        }
 51	    }
 52	
 53	    /**
 54	     * This is what the ant does most of the time: it eats grass
 55	     * and acacia. In the process, it might breed, die of hunger,
 56	     * or die of old age.
 57	     * @param newAnts A list to return newly born ants.
 58	     * @param time the current time in the simulation
 59	     */
 60	    public void act(List<Animal> newAnts, int time) {
 61	        incrementAge(MAX_AGE);
 62	        incrementHunger();
 63	
 64	        if(isAlive() && ((time >= 4)&&(time <= 20)))
 65	        {
 66	            if (getDisease()) {
 67	                spreadDisease();
 68	            }
 69	            if (giveBirth(BREEDING_AGE)) {
 70	                breedOffspring(newAnts, BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);
 71	            }
 72	
 73	            Location newLocation = findFood();
 74	            if(newLocation == null) {
 75	                newLocation = getField().freeAdjacentLocation(getLocation());
 76	            }
 77	            moveOrDie(newLocation);
 78	        }
 79	    }
 80	
 81	    /**
 82	     * Look for acacia and grass adjacent to the current location.
 83	     * Only the first grass or acacia is eaten.
 84	     * @return Where food was found, or null if it wasn't.
 85	     */
 86	    private Location findFood() {
 87	        Field field = getField();
 88	        List<Location> adjacent = field.adjacentLocations(getLocation());
 89	        Iterator<Location> it = adjacent.iterator();
 90	        while(it.hasNext()) {
 91	            Location where = it.next();
 92	            Object plant = field.getObjectAt(where);
 93	            if(plant instanceof Acacia) {
 94	                Acacia acacia = (Acacia) plant;
 95	                if (acacia.isAlive()) {
 96	                    acacia.setDead();
 97	                    setFoodLevel(ACACIA_FOOD_VALUE);
 98	                    return where;
 99	                }
100	            }
101	            else if (plant instanceof Grass) {
102	                Grass grass = (Grass) plant;
103	                if(grass.isAlive()) {
104	                    grass.setDead();
105	                    setFoodLevel(GRASS_FOOD_VALUE);
106	                    return where;
107	                }
108	            }
109	        }
110	        return null;
111	    }
112	
113	    /**
114	     * Create a new ant offspring.
115	     */
116	    protected Animal createOffspring(Field field, Location location) {
117	        return new Ant(false, field, location);
118	    }
119	
120	}

