48	     * if it can reproduce.
49	     * If it is raining, then the number of offspring is increased
50	     * @return The number of offspring (may be zero).
51	     */
52	    protected int breed(double REPRODUCING_PROBABILITY, int MAX_OFFSPRING_SIZE)
53	    {
54	        int offspring = 0;
