74	    /**
75	     * Reproduce into free adjacent locations.
76	     * @param newPlants A list to receive newly created plants.
77	     * @param REPRODUCING_PROBABILITY The likelihood of reproduction.
78	     * @param MAX_OFFSPRING_SIZE The maximum number of offspring.
79	     */
80	    protected void growPlants(List<Plant> newPlants, double REPRODUCING_PROBABILITY,
81	            int MAX_OFFSPRING_SIZE)
82	    {
83	        Field field = getField();
84	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
85	        int offspring = breed(REPRODUCING_PROBABILITY, MAX_OFFSPRING_SIZE);
86	        for(int b = 0; b < offspring && free.size() > 0; b++) {
